type EmailPlanRecord = {
  name: string;
  mailboxes: number;
  storageGB: number;
  priceCents: number;
  termMonths: number;
};

/** Build the marketing tier view-model from a db.emailPlan record. */
function tierFromPlan(p: EmailPlanRecord, popular: boolean): Tier {
  return {
    name: p.name,
    priceCents: p.priceCents,
    cadence: p.termMonths > 1 ? `/${p.termMonths} mo` : "/mo",
    tagline: TAGLINES[p.name] ?? "Professional email on your own domain.",
    features: [
      `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}`,
      `${p.storageGB} GB per mailbox`,
      "Webmail + IMAP/SMTP",
      "Spam & virus filtering",
    ],
    popular,
  };
}

